class BloomPage extends StatefulWidget {
  final PresentationState? state;
  final ValueChanged<BloomSuboption> onSub;
  final ValueChanged<String> onSyvax;
  final ValueChanged<BloomCapability>? onCapability;
  final VoidCallback onStewardship;
  final VoidCallback onHandoff;
  final bool busy;
  const BloomPage({super.key,required this.state,required this.onSub,required this.onSyvax,this.onCapability,required this.onStewardship,required this.onHandoff,required this.busy});
  @override State<BloomPage> createState()=>_BloomPageState();
}

class _BloomPageState extends State<BloomPage>{
  BloomCapability? selected;
  @override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);return LayoutBuilder(builder:(context,constraints){final compact=constraints.maxWidth<1100;return SingleChildScrollView(padding:EdgeInsets.all(compact?16:22),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[_HeroHeader(state:widget.state,selected:selected),const SizedBox(height:14),if(compact)Column(children:[_BloomCard(state:widget.state,selected:selected,onCapability:_select,onSub:widget.onSub,height:560),const SizedBox(height:14),_SandreQuickActions(state:widget.state,onOpen:widget.onStewardship,onHandoff:widget.onHandoff),const SizedBox(height:14),Syvax(onSubmit:widget.onSyvax,busy:widget.busy),const SizedBox(height:14),_ActivityPanel(state:widget.state)]) else Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:_BloomCard(state:widget.state,selected:selected,onCapability:_select,onSub:widget.onSub,height:600)),const SizedBox(width:16),SizedBox(width:320,child:Column(children:[_SandreQuickActions(state:widget.state,onOpen:widget.onStewardship,onHandoff:widget.onHandoff),const SizedBox(height:14),Syvax(onSubmit:widget.onSyvax,busy:widget.busy),const SizedBox(height:14),_ActivityPanel(state:widget.state)]))]),const SizedBox(height:14),_Lifecycle(state:widget.state),const SizedBox(height:10),Text('Criterivox stays alive through state, motion, handoff, and context. The visual layer reflects the system instead of inventing it.',style:TextStyle(color:t.mutedText,fontSize:10.5,height:1.45))]));});}
