}

class _HeroHeader extends StatelessWidget{final PresentationState? state;final BloomCapability? selected;const _HeroHeader({required this.state,required this.selected});@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);final selectedText=selected==null?'Choose a capability, then choose how you want to work with it.':'${Bloom.labels[selected!]} selected. Choose the relevant path.';return Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Living Interaction',style:TextStyle(color:t.text,fontSize:23,fontWeight:FontWeight.w700)),const SizedBox(height:4),Text(selectedText,style:TextStyle(color:t.mutedText,fontSize:11.5))])),if(state?.taskId!=null)Container(padding:const EdgeInsets.symmetric(horizontal:12,vertical:8),decoration:BoxDecoration(color:t.surfaceStrong,borderRadius:BorderRadius.circular(12),border:Border.all(color:t.border)),child:Text('TASK ${state!.taskId}',style:TextStyle(color:t.mutedText,fontSize:9,fontWeight:FontWeight.w700))) ]);}}

class _BloomCard extends StatelessWidget{final PresentationState? state;final BloomCapability? selected;final ValueChanged<BloomCapability> onCapability;final ValueChanged<BloomSuboption> onSub;final double height;const _BloomCard({required this.state,required this.selected,required this.onCapability,required this.onSub,required this.height});@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);return Container(height:height,padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:t.surface.withValues(alpha:.72),borderRadius:BorderRadius.circular(24),border:Border.all(color:t.border)),child:Column(children:[Container(padding:const EdgeInsets.symmetric(horizontal:16,vertical:10),decoration:BoxDecoration(color:t.surfaceStrong,borderRadius:BorderRadius.circular(16),border:Border.all(color:t.border)),child:Row(children:[Icon(Icons.auto_awesome_rounded,color:t.primary,size:18),const SizedBox(width:9),Expanded(child:Text('Choose a capability. Data Stewardship now routes to Sandre and the real foundation workflow.',style:TextStyle(color:t.mutedText,fontSize:10.5))),Icon(Icons.open_in_full_rounded,color:t.mutedText,size:16)])),const SizedBox(height:8),Expanded(child:Center(child:Bloom(onSelected:onCapability,selected:selected,onSuboption:onSub))) ]));}}

class _SandreQuickActions extends StatelessWidget{final PresentationState? state;final VoidCallback onOpen;final VoidCallback onHandoff;const _SandreQuickActions({required this.state,required this.onOpen,required this.onHandoff});@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);final foundation=state?.foundationId;final confirmed=state?.foundationConfirmation=='user-confirmed'||state?.foundationConfirmation=='user-corrected';return Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:t.surface,borderRadius:BorderRadius.circular(20),border:Border.all(color:t.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Icon(Icons.inventory_2_rounded,color:t.primary,size:19),const SizedBox(width:8),Expanded(child:Text('Sandre Quick Actions',style:TextStyle(color:t.text,fontSize:14,fontWeight:FontWeight.w700)))]),const SizedBox(height:6),Text(foundation==null?'No foundation is active.':'Foundation $foundation • ${state?.foundationCandidateCount??0} candidate(s) • ${state?.foundationConfirmation??'uncertain'}',style:TextStyle(color:t.mutedText,fontSize:9.5,height:1.35)),const SizedBox(height:12),_action('Open Data Stewardship',Icons.folder_special_rounded,onOpen,t),_action('Review Foundation',Icons.fact_check_outlined,onOpen,t),_action('Handoff to Dharen',Icons.send_rounded,confirmed?onHandoff:null,t)]));}
