class _ActivityPanel extends StatelessWidget{final PresentationState? state;const _ActivityPanel({required this.state});@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);final items=<String>[if(state?.message!=null)state!.message!,...?state?.activity.take(3),'Analysis workspace is available from the same task.','Syvax can route a request to Dharen.'];return Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:t.surface,borderRadius:BorderRadius.circular(20),border:Border.all(color:t.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text('Recent Activity',style:TextStyle(color:t.text,fontSize:15,fontWeight:FontWeight.w700))),Text(state?.error==null?'LIVE':'WARNING',style:TextStyle(color:state?.error==null?t.success:t.warning,fontSize:9,fontWeight:FontWeight.w800))]),const SizedBox(height:14),for(final item in items.take(6))Padding(padding:const EdgeInsets.only(bottom:12),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.circle,size:6,color:t.primary),const SizedBox(width:10),Expanded(child:Text(item,style:TextStyle(color:t.mutedText,fontSize:10.5,height:1.4)))]))]));}}

class _Lifecycle extends StatelessWidget{final PresentationState? state;const _Lifecycle({required this.state});@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);final active=state?.taskState??'READY';final stages=['CREATED','RECEIVED','VALIDATING','PROCESSING','ANALYZING','RESULT_READY','COMPLETED'];final activeIndex=stages.indexOf(active.toUpperCase());return Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:t.surface,borderRadius:BorderRadius.circular(20),border:Border.all(color:t.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('TASK LIFECYCLE',style:TextStyle(color:t.mutedText,fontSize:10,fontWeight:FontWeight.w700,letterSpacing:1.1)),const SizedBox(height:18),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(mainAxisSize:MainAxisSize.min,children:[for(var i=0;i<stages.length;i++)Row(children:[Column(mainAxisSize:MainAxisSize.min,children:[Container(width:30,height:30,decoration:BoxDecoration(shape:BoxShape.circle,color:i<=activeIndex?t.primary.withValues(alpha:.15):t.surfaceStrong,border:Border.all(color:i<=activeIndex?t.primary:t.border)),child:Icon(i==6?Icons.check_rounded:Icons.auto_awesome_rounded,size:14,color:i<=activeIndex?t.primary:t.mutedText)),const SizedBox(height:6),Text(stages[i].replaceAll('_',' '),style:TextStyle(color:i==activeIndex?t.text:t.mutedText,fontSize:8.5,fontWeight:FontWeight.w600))]),if(i<stages.length-1)Container(width:42,height:1,margin:const EdgeInsets.symmetric(horizontal:6,vertical:15),color:t.border)])])),const SizedBox(height:10),Text('Current state: $active',style:TextStyle(color:t.mutedText,fontSize:10))]));}
